[[nodiscard]] std::optional<std::ptrdiff_t> first_index(std::span<const int> sorted, int value) {
  std::ptrdiff_t lo = 0;
  std::ptrdiff_t hi = std::ssize(sorted);
  // Invariant: every element before lo is < value, and every element from hi on is >= value.
  while (lo < hi) {
    const std::ptrdiff_t mid = lo + (hi - lo) / 2;
    if (sorted[mid] < value)
      lo = mid + 1;
    else
      hi = mid;
  }
  if (lo < std::ssize(sorted) && sorted[lo] == value) return lo;
  return std::nullopt;
}

[[nodiscard]] std::string show(std::optional<std::ptrdiff_t> index) {
  return index ? std::to_string(*index) : "no value";
}

int main() {
  const std::vector<int> v{1, 2, 2, 2, 3, 5};
  for (const int x : {2, 1, 5, 3, 0, 4, 6}) std::cout << std::format("{}: {}\n", x, show(first_index(v, x)));
  std::cout << std::format("empty: {}\n", show(first_index({}, 2)));
}

