int main() {
  const std::vector<int> v{10, 20, 20, 20, 30, 40};
  const auto index = [&v](auto it) { return it - v.begin(); };

  std::cout << std::format("lower_bound(20) = {}\n", index(std::ranges::lower_bound(v, 20)));
  std::cout << std::format("upper_bound(20) = {}\n", index(std::ranges::upper_bound(v, 20)));
  const auto [first, last] = std::ranges::equal_range(v, 20);
  std::cout << std::format("equal_range(20) = [{}, {})\n", index(first), index(last));
  std::cout << std::format("lower_bound(25) = {}, lower_bound(50) = {}\n", index(std::ranges::lower_bound(v, 25)),
                           index(std::ranges::lower_bound(v, 50)));
  std::cout << std::format("partition_point(x < 25) = {}\n",
                           index(std::ranges::partition_point(v, [](int x) { return x < 25; })));
}

#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <numeric>
#include <ranges>
#include <span>
#include <vector>

// Can a battery of this capacity drive the legs in order, recharging at most `recharges` times between legs?
[[nodiscard]] bool completes(std::span<const std::int64_t> legs, std::int64_t capacity_m, std::int64_t recharges) {
  std::int64_t charge_m = capacity_m;
  for (const std::int64_t leg : legs) {
    if (leg > capacity_m) return false;  // no full battery drives this leg
    if (leg > charge_m) {                // recharge before this leg
      if (recharges == 0) return false;
      --recharges;
      charge_m = capacity_m;
    }
    charge_m -= leg;
  }
  return true;
}

int main() {
  const std::vector<std::int64_t> legs{7, 2, 5, 10, 8};
  const std::int64_t longest = std::ranges::max(legs);
  const std::int64_t total = std::accumulate(legs.begin(), legs.end(), std::int64_t{0});

  // Invariant: every capacity below lo fails, and every capacity from hi on completes.
  std::int64_t lo = longest;
  std::int64_t hi = total + 1;
  while (lo < hi) {
    const std::int64_t mid = lo + (hi - lo) / 2;
    const bool ok = completes(legs, mid, 1);
    std::cout << std::format("lo {:2}  hi {:2}  mid {:2}  {}\n", lo, hi, mid, ok ? "completes" : "fails");
    if (ok)
      hi = mid;
    else
      lo = mid + 1;
  }
  std::cout << std::format("by hand: {} m\n", lo);

  const auto capacities = std::views::iota(longest, total + 1);
  const auto it = std::ranges::partition_point(capacities, [&](std::int64_t c) { return !completes(legs, c, 1); });
  std::cout << std::format("partition_point: {} m\n", *it);
}

#include <algorithm>
