#include <string>
#include <vector>

struct Sample {
  std::int64_t stamp_ms;  // strictly increasing
  double yaw_rad;
};

[[nodiscard]] std::optional<std::ptrdiff_t> find_exact(std::span<const Sample> samples, std::int64_t stamp_ms) {
  const auto it = std::ranges::lower_bound(samples, stamp_ms, {}, &Sample::stamp_ms);
  if (it == samples.end() || it->stamp_ms != stamp_ms) return std::nullopt;
  return it - samples.begin();
}

// The sample closest in time to stamp_ms; the earlier one on a tie.
[[nodiscard]] std::optional<std::ptrdiff_t> nearest(std::span<const Sample> samples, std::int64_t stamp_ms) {
  if (samples.empty()) return std::nullopt;
  const auto after = std::ranges::lower_bound(samples, stamp_ms, {}, &Sample::stamp_ms);  // first at or after
  if (after == samples.begin()) return 0;
  if (after == samples.end()) return std::ssize(samples) - 1;
  const auto before = std::prev(after);
  const bool earlier_wins = stamp_ms - before->stamp_ms <= after->stamp_ms - stamp_ms;
  return (earlier_wins ? before : after) - samples.begin();
}

[[nodiscard]] std::string show(std::optional<std::ptrdiff_t> index) {
  return index ? std::to_string(*index) : "no value";
}

int main() {
  std::vector<Sample> samples;
  for (const std::int64_t stamp : {100, 110, 120, 135, 150}) samples.push_back({.stamp_ms = stamp, .yaw_rad = 0.0});

  for (const std::int64_t stamp : {120, 125, 99, 150})
    std::cout << std::format("exact {}: {}\n", stamp, show(find_exact(samples, stamp)));
  for (const std::int64_t stamp : {125, 130, 115, 10, 999})
    std::cout << std::format("nearest {}: {}\n", stamp, show(nearest(samples, stamp)));
  std::cout << std::format("nearest in no samples: {}\n", show(nearest({}, 125)));
}

