using Occurrences = std::optional<std::pair<std::ptrdiff_t, std::ptrdiff_t>>;

// The first index in [0, n) where pred is true, or n; pred must be false for a first stretch, then true.
template <typename Pred>
[[nodiscard]] std::ptrdiff_t first_true(std::ptrdiff_t n, Pred pred) {
  std::ptrdiff_t lo = 0;
  std::ptrdiff_t hi = n;
  while (lo < hi) {
    const std::ptrdiff_t mid = lo + (hi - lo) / 2;
    if (pred(mid))
      hi = mid;
    else
      lo = mid + 1;
  }
  return lo;
}

[[nodiscard]] Occurrences first_and_last_by_hand(std::span<const int> sorted, int value) {
  const std::ptrdiff_t n = std::ssize(sorted);
  const std::ptrdiff_t first = first_true(n, [&](std::ptrdiff_t i) { return sorted[i] >= value; });
  const std::ptrdiff_t end = first_true(n, [&](std::ptrdiff_t i) { return sorted[i] > value; });
  if (first == end) return std::nullopt;
  return std::pair{first, end - 1};
}

[[nodiscard]] Occurrences first_and_last(std::span<const int> sorted, int value) {
  const auto found = std::ranges::equal_range(sorted, value);
  if (found.empty()) return std::nullopt;
  return std::pair{found.begin() - sorted.begin(), found.end() - sorted.begin() - 1};
}

int main() {
  const std::vector<std::vector<int>> arrays{{1, 2, 2, 2, 3}, {7, 7, 7, 7}, {5}, {}};
  bool agree = true;
  for (const std::vector<int>& a : arrays)
    for (int value = 0; value <= 8; ++value)
      agree = agree && first_and_last(a, value) == first_and_last_by_hand(a, value);
  std::cout << std::format("hand-written and equal_range agree: {}\n", agree);

  for (const int value : {2, 1, 3, 4}) {
    const Occurrences r = first_and_last(arrays[0], value);
    if (r) std::cout << std::format("{}: first {}, last {}, count {}\n", value, r->first, r->second, r->second - r->first + 1);
    else std::cout << std::format("{}: no value\n", value);
  }
}

#include <algorithm>
#include <cstddef>
#include <format>
#include <iostream>
#include <optional>
#include <ranges>
#include <span>
#include <vector>

[[nodiscard]] std::optional<std::ptrdiff_t> find_rotated(std::span<const int> v, int value) {
  if (v.empty()) return std::nullopt;
  const auto split = std::ranges::partition_point(v, [&](int x) { return x >= v.front(); });
  const auto run = value >= v.front() ? std::ranges::subrange(v.begin(), split) : std::ranges::subrange(split, v.end());
  const auto it = std::ranges::lower_bound(run, value);
  if (it == run.end() || *it != value) return std::nullopt;
  return it - v.begin();
}

// The one-loop version: one side of mid is always sorted.
[[nodiscard]] std::optional<std::ptrdiff_t> find_rotated_one_loop(std::span<const int> v, int value) {
  std::ptrdiff_t lo = 0;
  std::ptrdiff_t hi = std::ssize(v);  // if value is in v, it is in [lo, hi)
  while (lo < hi) {
    const std::ptrdiff_t mid = lo + (hi - lo) / 2;
    if (v[mid] == value) return mid;
    if (v[lo] <= v[mid]) {  // [lo, mid] is sorted
      if (v[lo] <= value && value < v[mid])
        hi = mid;
      else
        lo = mid + 1;
    } else {  // [mid, hi) is sorted
      if (v[mid] < value && value <= v[hi - 1])
        lo = mid + 1;
      else
        hi = mid;
    }
  }
  return std::nullopt;
}

int main() {
  const std::vector<int> sorted{0, 10, 20, 30, 40, 50, 60};
  bool all_right = true;
  for (std::ptrdiff_t shift = 0; shift < std::ssize(sorted); ++shift) {
    std::vector<int> v = sorted;
    std::ranges::rotate(v, v.begin() + shift);
    for (int value = -5; value <= 65; value += 5) {
      const auto found = std::ranges::find(v, value);
      const std::optional<std::ptrdiff_t> expected =
          found == v.end() ? std::nullopt : std::optional<std::ptrdiff_t>{found - v.begin()};
      all_right = all_right && find_rotated(v, value) == expected && find_rotated_one_loop(v, value) == expected;
    }
  }
  std::cout << std::format("7 rotations, 15 values each, both versions right: {}\n", all_right);

  const std::vector<int> v{40, 50, 60, 0, 10, 20, 30};
  std::cout << std::format("10 is at {}, 50 is at {}, 35 found: {}\n", find_rotated(v, 10).value(),
                           find_rotated(v, 50).value(), find_rotated(v, 35).has_value());
  std::cout << std::format("empty: {}\n", find_rotated({}, 10).has_value());
}

#include <format>
#include <iostream>
#include <limits>

[[nodiscard]] int first_at_least(int target) {
  int lo = 0;
  int hi = std::numeric_limits<int>::max();
  while (lo < hi) {
    const int mid = (lo + hi) / 2;
    if (mid < target)
      lo = mid + 1;
    else
      hi = mid;
  }
  return lo;
}

int main() {
  std::cout << std::format("{}\n", first_at_least(1000));
  std::cout << std::format("{}\n", first_at_least(2'000'000'000));
}

#include <format>
#include <iostream>
#include <limits>
#include <numeric>

[[nodiscard]] int first_at_least(int target) {
  int lo = 0;
  int hi = std::numeric_limits<int>::max();
  while (lo < hi) {
    const int mid = std::midpoint(lo, hi);  // never overflows; rounds towards lo
    if (mid < target)
      lo = mid + 1;
    else
      hi = mid;
  }
  return lo;
}

int main() {
  std::cout << std::format("{}\n", first_at_least(2'000'000'000));
  std::cout << std::format("midpoint(-2000000000, 2000000000) = {}\n", std::midpoint(-2'000'000'000, 2'000'000'000));
  std::cout << std::format("midpoint(4, 7) = {}, midpoint(7, 4) = {}\n", std::midpoint(4, 7), std::midpoint(7, 4));
}

#include <cstddef>
#include <format>
#include <iostream>
#include <optional>
#include <span>
#include <vector>

// Closed range [lo, hi] with unsigned indices.
[[nodiscard]] std::optional<std::size_t> find(std::span<const int> v, int value) {
  std::size_t lo = 0;
  std::size_t hi = v.size() - 1;
  while (lo <= hi) {
    const std::size_t mid = lo + (hi - lo) / 2;
    if (v[mid] == value) return mid;
    if (v[mid] < value)
      lo = mid + 1;
    else
      hi = mid - 1;
  }
  return std::nullopt;
}

int main() {
  const std::vector<int> v{10, 20, 30};
  std::cout << std::format("found 5: {}\n", find(v, 5).has_value());
}
